// 1. Grab the current order selections
const order = $input.first().json;
const selections = order.selections;
// 2. Grab the NLP entities (what the user just said)
const entities = $('HTTP Request1').first().json.entities;
// 3. Dynamic Merge: Loop through entities and patch selections
for (const key in entities) {
  // If the key exists in your order selections, update it
  if (selections.hasOwnProperty(key) && entities[key] != null) {
    selections[key] = entities[key];
  }

  // SPECIAL CASE: 'quantity' in NLP usually maps to 'size' in your DB
  if (key === 'quantity') {
    selections['size'] = entities[key];
  }


}

// 4. Return the updated order object
return {
  selections: selections
};

const selections = $input.first().json.selections

const configData = $('Select Config').first().json.config_data;

for (var key in configData) {
  if(configData[key].depends_on != null){
    var dependent_field = configData[key].depends_on.field
    var dependent_values = configData[key].depends_on.expected
    if(dependent_values.includes(selections[dependent_field])){
      selections[dependent_field] = null
    }
  }
}

return{selections:selections}

// 1. Get the current state
const selections = $input.first().json.selections;
const requirements = $('Config Data Init').first().json.config_data;
const turn_count = $input.first().json.turn_count;

// 2. Identify ALL keys that are currently null
const allMissingKeys = Object.keys(selections).filter(key => selections[key] === null);

if (allMissingKeys.length === 0) {
    return { status: 'complete' };
}

/**
 * 3. Dynamic Throttling:
 * If we are deep in the conversation (turn > 5), 
 * focus on 1 question at a time to reduce friction.
 */
const batchLimit = (turn_count > 5) ? 1 : 3;
const nextBatch = allMissingKeys.slice(0, batchLimit);

// 4. Map those keys to their human-friendly questions
const questionsToAsk = nextBatch.map(key => requirements[key].prompt_question);

return {
    status: 'incomplete',
    turn_count: turn_count,
    missingCount: allMissingKeys.length,
    batchSize: nextBatch.length,
    missingKeys: nextBatch,
    // Join questions with a space for a natural reading flow
    combinedQuestion: questionsToAsk.join(" ") 
};

const s = $input.first().json.selections;

// Clean up the display values (handling nulls/formatting)
const summary = [
    `👤 *Name:* ${s.client_name || 'Not set'}`,
    `🎂 *Cake:* ${s.flavor} (${s.size} inch)`,
    `🥞 *Structure:* ${s.tier} Tiers / ${s.layer} Layers`,
    `🎨 *Theme:* ${s.cake_theme}`,
    `📅 *Event Date:* ${s.event_date}`,
    `📝 *Notes:* ${s.special_notes || 'None'}`,
    `🚚 *Method:* ${s.delivery}`
];

// Dynamically add address if it exists
if (s.delivery === 'Delivery' && s.delivery_address) {
    summary.push(`📍 *Address:* ${s.delivery_address}`);
}
// 5. THE END: The Confirmation Question
summary.push(`\n---\n`);
summary.push(`*Does everything look correct?*\n\n`);
summary.push(`✅ Reply *'Yes'* to proceed to payment.\n`);
summary.push(`✏️ Reply with the change you'd like to make (e.g., "Change the flavor to Chocolate").`);

return {
    summary: summary.join('\n'),
};

