const selections = $('Execute a SQL query1').first().json.selections;
const aiOutput = JSON.parse($('AI Agent').first().json.output)
const extracted = aiOutput.extracted_data

// Step 1: Filter out nulls from the LLM so they don't overwrite existing values
const filteredNewData = Object.fromEntries(
  Object.entries(extracted).filter(([_, value]) => value !== null)
);

// Step 2: Merge locally for the 'completion' check
const mergedSelections = { ...selections, ...filteredNewData };

// Step 3: Check for completion (any nulls left?)
// Note: We check against the keys in 'pruned_slots'

return {
  selections: mergedSelections,
};

const payload = $input.first().json.payload
